import logging

import attr
from typing import List, Optional, Dict


@attr.s(cmp=False)
class Pdu(object):
    """

    :param str addr: IP ADDRESS or FQDN
    :param List[int] port_numbers: List of Port numbers on the PDU
    :param Optional[str] model: model of the PDU, e.g. "EPC"
    :param Optional[str] version: exact version of the PDU, e.g. "8221-1"
    """
    addr = attr.ib(type=str)
    port_numbers = attr.ib(repr=False, type=List[int])
    pdu_ports = attr.ib(init=False)
    vendor = attr.ib(init=False)
    model = attr.ib(default=None, type=Optional[str])
    version = attr.ib(default=None, type=Optional[str])

    def __attrs_post_init__(self):
        self.pdu_ports = {i: PduPort(self, i) for i in self.port_numbers}
        self.vendor = self.__class__.__name__

    def __taf_contract_pdu__(self):
        return {
            "addr": self.addr,
            "model": self.model if self.model else self.vendor,
            "model_specific_parameters": {"version": self.version, },
        }


@attr.s(cmp=False)
class PduPort(object):
    """

    :param Pdu pdu: object of subclass of Pdu
    :param int port_no: Port/Outlet number on the PDU
    :param Optional[str] contactor: Behavior of contactor when powered on by PDU
      (NORMALLY_OPENED - circuit open when powered on (default behavior),
      NORMALLY_CLOSED - circuit closed when powered on)
    """
    pdu = attr.ib(type=Pdu)
    port_no = attr.ib(type=int)
    contactor = attr.ib(default="NORMALLY_OPENED", type=Optional[str])


